mponentAPI(\"Checkbox\").APIs(\"produceTask.formulaId.batchContral\").getValue()[\"value\"];\nif (isBatch) {\n\tReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575440429718\").setColumnsHideOrShow(\"execSort\");\n}","regionType":"DATAGRID","convertPdfOnLine":true,"modelCode":"WOM_1.0.0_produceTask_TaskActive","rowspan":1,"complex":true,"autoAddRow":false,"showType":"DATAGRID","isgroup":false,"isCreateNew":false,"renderOver":"// 工单活动表\nlet dataGrid = ReactAPI.getComponentAPI(''SupDataGrid'').APIs(''WOM_1.0.0_produceTask_makeTaskEditdg1575440429718'');\nlet actives = dataGrid.getDatagridData();\nfor (let i = 0; i < actives.length; i++) {\n    // 活动类型\n    let activeType = actives[i].activeType.id;\n    if (activeType === \"RM_activeType/batchPutin\" || activeType === \"RM_activeType/pipeBatchPutin\") {\n        // 如果是投配料活动\n        dataGrid.setRowAttr(i, { style: { background: \"#cae6ff\" } })\n    } else if (activeType === \"RM_activeType/batch\" || activeType === \"RM_activeType/pipeBatch\") {\n        // 如果是配料活动\n        dataGrid.setRowAttr(i, { style: { background: \"#daf4d7\" } })\n    }\n}\n//判断物料是否为危化品\nlet materialId=[];\nlet id;\nfor(let i=0;i<actives.length;i++){\n    if(actives[i].materialId!=null&&actives[i].materialId.id!=null){\n        materialId.push({ \"materialId\":actives[i].materialId.id });\n    }\n    else\n        materialId.push({ \"materialId\":-1 });\n}  \nif(actives.length!=0&&materialId.length!=0){//如果物料编码字段不为空，则发送请求\n    ReactAPI.request({\n        type: \"post\",\n        url: \"/msService/WOM/produceTask/produceTask/GetMaterialAttributes\",\n        contentType: \"application/json;charset=UTF-8\",\n        data: JSON.stringify(materialId)// 将json数据转化为字符\n    }, function (res) {\n        if(res.success){\n          for(let i=0;i<actives.length;i++){//遍历\n            if(res.data[i]!=null&&res.data[i]==true){//如果是危化品则为红色\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#B30303\" } });\t\n               // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n            }\n            else if(res.data[i]!=null&&res.data[i]==false){\n                ReactAPI.getComponentAPI(\"SupDataGrid\")\n                .APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\")\n                .setDatagridCellAttr(i, \"materialId.code\", { style: { color: \"#505050\" } });\n               // console.log(\"i=\"+i+\",res.data=\"+res.data[i]);\n            }\n          }\n        }else{\t\n            console.log(res.msg);\n        }\n    }\n    );\n}","isEasyTable":false,"firstTd":1,"officeNotNull":false,"copyColumn":false,"cellCode":"cell_1575440636575_8956","isTransCondition":false,"nodeExpanded":false,"importExcel":false,"isOfficeSign":false,"columnType":"DATAGRID","isTitle":true,"dataGridName":"dg1575440429718","hasFastQuery":false,"fields":[{"showTypeHasChanged":true,"precisionHasChanged":false,"onlyLeaf":false,"code":"WOM_1.0.0_produceTask_makeTaskEditdg1575440429718_DATAGRID_OTHER_WOM_1.0.0_produceTask_TaskActive_taskProcessId_WOM_1.0.0_produceTask_TaskProcess_name","nullable":true,"isTotal":false,"displayName":"WOM.produceTask.TaskProcess.name","showFormatHasChanged":true,"defaultValueHasChanged":false,"isCount":false,"dbColumnType":"TEXT","propertyCode":"WOM_1.0.0_produceTask_TaskActive_taskProcessId||WOM_1.0.0_produceTask_TaskProcess_name","regionType":"DATAGRID","layRec":"WOM_TASK_PROCESSES,ID,WOM_TASK_ACTIVES,TASK_PROCESS_ID-name","modelCode":"WOM_1.0.0_produceTask_TaskProcess","namekey":"WOM.produceTask.TaskProcess.name","isreadonly":false,"showType":"SELECTCOMP","isgroup":false,"key":"taskProcessId.name","popView":false,"showFormat":"SELECTCOMP","entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","cellCode":"cell_1575440787890_5006","mneenable":false,"label":"工序名称","fullPropertyCode":"WOM_