"WOM_1.0.0_produceTask_ProduceTask","complex":false,"isgroup":false,"showType":"TEXTFIELD","isCreateNew":false,"officeNotNull":false,"mneenable":false,"isOfficeSign":false,"columnType":"DECIMAL","isTitle":true,"isrefselect":false,"name":"produceTask.actualPlanNum","isNoCopy":false,"maxLength":null,"precisionHasChanged":true,"acceptRevisions":false,"code":"WOM_1.0.0_produceTask_makeTaskEdit_EDIT_OTHER_WOM_1.0.0_produceTask_ProduceTask_actualPlanNum","displayName":"WOM.propertyshowName.randon1614586075263.flag","multallowview":false,"hideRevision":false,"getRevisions":false,"allowview":false,"showRevision":false,"namekey":"WOM.propertyshowName.randon1614586075263.flag","isreadonly":true,"officePrint":false,"key":"produceTask.actualPlanNum","downloadDoc":true,"entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","showFormat":"TEXT","autoresize":false,"fullPropertyCode":"WOM_1.0.0_produceTask_ProduceTask_actualPlanNum","saveTemplate":false,"isCustom":false,"openEmptyDoc":true,"multable":false,"columnName":"ACTUAL_PLAN_NUM"}},{"colspan":1,"firstTd":1,"regionType":"EDIT","rowspan":1,"cellCode":"cell_1577348327986_8162","name":"配方编码","type":"layoutCell","element":{"showTypeHasChanged":false,"couple":true,"onlyLeaf":false,"iscontrol":false,"nullable":false,"isOfficeHandSign":false,"isRevision":false,"showFormatHasChanged":false,"dbColumnType":"BAPCODE","propertyCode":"WOM_1.0.0_produceTask_ProduceTask_formulaId||RM_1.0.0_formula_Formula_formualCode","elalign":"right","readonly":false,"convertPdfOnLine":true,"modelCode":"RM_1.0.0_formula_Formula","complex":false,"isgroup":false,"showType":"LABEL","isCreateNew":false,"officeNotNull":false,"mneenable":false,"isOfficeSign":false,"columnType":"BAPCODE","isTitle":true,"isrefselect":false,"name":"配方编码","isNoCopy":false,"maxLength":2000,"acceptRevisions":false,"code":"WOM_1.0.0_produceTask_makeTaskEdit_EDIT_LABEL_WOM_1.0.0_produceTask_ProduceTask_formulaId_RM_1.0.0_formula_Formula_formualCode","displayName":"RM.formula.Formula.formualCode","multallowview":false,"hideRevision":false,"getRevisions":false,"allowview":false,"showRevision":false,"namekey":"RM.formula.Formula.formualCode","isreadonly":false,"officePrint":false,"key":"produceTask.formulaId.formualCode","downloadDoc":true,"entityCode":"WOM_1.0.0_produceTask","moduleCode":"WOM_1.0.0","showFormat":"TEXT","autoresize":false,"fullPropertyCode":"WOM_1.0.0_produceTask_ProduceTask_formulaId||RM_1.0.0_formula_Formula_formualCode","saveTemplate":false,"isCustom":false,"openEmptyDoc":true,"multable":false,"columnName":"FORMUAL_CODE"}},{"callbackbody_es5":"function formulaRefCallback(formulas) {\n    if (!formulas.length) {\n        return;\n    }\n    var formula = formulas[0];\n    // 选中产品后，如有该产品的默认配方，直接带出\n    var product = formula.productId;\n    // 产品输入框\n    var productComponent = ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.productId.code'');\n    productComponent.setValue(product);\n    // 设置是否批控\n    ReactAPI.getComponentAPI(''Checkbox'').APIs(''produceTask.batchContral'').setValue(formula.batchContral);\n    // 适用产线清空\n    ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.lineId.name'').removeValue();\n    // 工序活动、用料汇总、检验清单页签均隐藏\n    $(\"[role=''tab'']:gt(0)\").hide();\n    var dataGrid = ReactAPI.getComponentAPI(\"SupDataGrid\").APIs(\"WOM_1.0.0_produceTask_makeTaskEditdg1575441036618\");\n    if (formula.setProcess.id == ''RM_formulaType/simpleFormula'') {\n        dataGrid.setColumnsHideOrShow(\"taskProcessId.name\", false);\n        dataGrid.setColumnsHideOrShow(\"name\", false);\n        dataGrid.setColumnsHideOrShow(\"activeType\", false);\n    } else {\n        dataGrid.setColumnsHideOrShow(\"taskProcessId.name\", true);\n        dataGrid.setColumnsHideOrShow(\"name\", true);\n        dataGrid.setColumnsHideOrShow(\"activeType\", true);\n    }\n    //检验时机\n    var inspectTimer = ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.inspectTimer\");\n    inspectTimer.setReadonly(true);\n    if (formulas[0].inspectTimer != null) {\n        inspectTimer.setValue(formulas[0].inspectTimer.id);\n        var inspectValue = inspectTimer.getValue().value;\n        if (inspectValue != '''' && inspectValue != \"RM_inspectTimer/active\") {\n            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(true);\n            ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(true);\n            ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(false);\n        }\n    } else {\n        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setRequired(false);\n        ReactAPI.getComponentAPI().Label.APIs(''produceTask.qualityStdId.name'').setNullableStyle(false);\n        ReactAPI.getComponentAPI(''Reference'').APIs(''produceTask.qualityStdId.name'').setReadonly(true);\n    }\n    //\n    var qualityStdId = ReactAPI.getComponentAPI().Reference.APIs(''produceTask.qualityStdId.name'');\n    if (formulas[0].qualityStdId && formulas[0].qualityStdId.id) {\n        qualityStdId.setValue(formulas[0].qualityStdId);\n    } else {\n        qualityStdId.removeValue();\n    }\n    //报工模式 \n    if (formula.reportType != undefined) {\n        ReactAPI.getComponentAPI(\"SystemCode\").APIs(\"produceTask.reportType\").setValue(formula.reportType.id);\n    }\n    // ''允许提前放料''及''放料条件''\n    var advanceCharge = ReactAPI.getComponentAPI().Checkbox.APIs(''produceTask.advanceCharge'');\n    var feedCondition = ReactAPI.getComponentAPI().Input.APIs(''produceTask.feedCondition'');\n    advanceCharge.setValue(formulas[0].advanceCharge ? true : false);\n    feedCondition.setReadonly(formulas[0].advanceCharge ? false : true);\n    feedCondition.setValue(formulas[0].feedCondition);\n    // 改变配方编码的点击样式\n    $(''#label_produceTask_formulaId_formualCode'').html(window._supcon_target_html);\n}","callbackbody":"function formulaRefCallback(formulas) {\n   